// A study pack exists once. Assignment numbers and course records belong to a profile.
import {WORLDS} from './worlds.js';
export function ensureLevels(p){p.levels??=[];const known=new Set(p.levels.map(l=>l.packId));for(const id of [p.activePack,...Object.keys(p.learning||{}),...Object.keys(p.runs||{})])if(id&&!known.has(id)){p.levels.push({packId:id,number:p.levels.length+1,archived:false});known.add(id);}p.selectedLevel??=p.activePack;p.courses??={};p.levelProgress??={};p.rewardBook??={runs:{},days:{}};for(const r of Object.values(p.runs||{})){const key=courseKey(r.packId,r.theme);p.courses[key]??=r;}return p.levels;}
export const courseKey=(packId,world)=>packId+'~'+world;
export function migrateLevelHistory(p){ensureLevels(p);if(p.levelHistoryMigrated)return;for(const r of Object.values(p.runs||{})){const ids=r.claimedStages||[];if(!ids.length&&r.mode!=='victory')continue;const stages=r.mode==='victory'?[0,1,2]:ids,pr=levelProgress(p,r.packId);pr.worlds[r.theme]??={stages:stages.length,finishes:stages.includes(2)?1:0,bestScore:Math.floor(r.score||0),stageIds:[...stages]};if(stages.includes(2))pr.completed=true;}p.levelHistoryMigrated=true;}
export function courseFor(p,packId,world){ensureLevels(p);return p.courses[courseKey(packId,world)]||((p.runs[packId]?.theme===world)?p.runs[packId]:null);}
export function assignLevel(data,profile,packId,current=true){const p=data.profiles[profile];ensureLevels(p);if(!Object.hasOwn(data.packs,packId))throw Error('Choose an existing study pack.');let level=p.levels.find(l=>l.packId===packId);if(!level){level={packId,number:Math.max(0,...p.levels.map(l=>l.number))+1,archived:false};p.levels.push(level);}if(current){p.activePack=packId;p.selectedLevel=packId;level.archived=false;if(data.packs[packId].archived)data.packs[packId].archived=false;}return level;}
export function isPast(p,pack){ensureLevels(p);return p.activePack!==pack.id||!!pack.archived||!!p.levels.find(l=>l.packId===pack.id)?.archived;}
export function levelProgress(p,packId){ensureLevels(p);return p.levelProgress[packId]??={worlds:{},completed:false,dust:0,xpDust:0};}
export function archiveLevel(p,id,packs={}){ensureLevels(p);const level=p.levels.find(l=>l.packId===id);if(!level)return false;if(p.activePack===id){const next=[...p.levels].reverse().find(l=>l.packId!==id&&!l.archived&&!packs[l.packId]?.archived);if(!next)return false;p.activePack=next.packId;}level.archived=true;return true;}
export function validLevels(p,packs){if(p.levels===undefined)return true;if(!Array.isArray(p.levels)||p.levels.length>500)return false;const ids=new Set(),nums=new Set();for(const l of p.levels){if(!l||!Object.hasOwn(packs,l.packId)||ids.has(l.packId)||nums.has(l.number)||!Number.isSafeInteger(l.number)||l.number<1||typeof l.archived!=='boolean')return false;ids.add(l.packId);nums.add(l.number);}if(p.selectedLevel&&!ids.has(p.selectedLevel))return false;for(const [id,pr]of Object.entries(p.levelProgress||{})){if(!Object.hasOwn(packs,id)||!pr?.worlds||typeof pr.completed!=='boolean'||![pr.dust,pr.xpDust].every(n=>Number.isFinite(n)&&n>=0&&n<1.001))return false;for(const [world,w]of Object.entries(pr.worlds))if(!Object.hasOwn(WORLDS,world)||!w||![w.stages,w.finishes,w.bestScore].every(n=>Number.isSafeInteger(n)&&n>=0))return false;}return true;}
